  <script>
    // Dualkit Rules Implementation
    document.addEventListener('DOMContentLoaded', () => {
      // 1. Arabic Plural System (6 plural forms handled via Intl.PluralRules)
      const itemCount = 3;
      const pluralForms = {
        zero: 'لا توجد عناصر في هذا الطلب',
        one: 'لديك عنصر واحد في هذا الطلب',
        two: 'لديك عنصران في هذا الطلب',
        few: 'لديك {count} عناصر في هذا الطلب',
        many: 'لديك {count} عنصرًا في هذا الطلب',
        other: 'لديك {count} عنصر في هذا الطلب'
      };

      // Format count with Western digits pinned (standard in UAE financial apps)
      const digitsFormatter = new Intl.NumberFormat('ar-AE-u-nu-latn');
      const pluralCategory = new Intl.PluralRules('ar').select(itemCount);
      const pluralElement = document.getElementById('plural-text');
      if (pluralElement) {
        pluralElement.textContent = pluralForms[pluralCategory].replace('{count}', digitsFormatter.format(itemCount));
      }

      // 2. Dates formatted explicitly with timeZone: 'Asia/Dubai' and islamic-umalqura calendar
      const targetDueDate = new Date(2026, 10, 3); // 3 November 2026

      try {
        // Umm al-Qura Hijri Calendar formatting
        const hijriFormatter = new Intl.DateTimeFormat('ar-AE-u-ca-islamic-umalqura-nu-latn', {
          timeZone: 'Asia/Dubai',
          day: 'numeric',
          month: 'long',
          year: 'numeric'
        });
        const formattedHijri = hijriFormatter.format(targetDueDate);
        const hijriEl = document.getElementById('date-hijri');
        if (hijriEl) {
          hijriEl.textContent = `${formattedHijri} هـ`;
        }

        // Gregorian Calendar formatting
        const gregFormatter = new Intl.DateTimeFormat('ar-AE-u-nu-latn', {
          timeZone: 'Asia/Dubai',
          day: 'numeric',
          month: 'long',
          year: 'numeric'
        });
        const formattedGreg = gregFormatter.format(targetDueDate);
        const gregEl = document.getElementById('date-gregorian');
        if (gregEl) {
          gregEl.textContent = `${formattedGreg} م`;
        }
      } catch (e) {
        // Robust fallback if custom calendar extension is not supported by environment
        console.warn('Umm al-Qura calendar formatting fallback:', e);
      }

      // 3. Normalise typed Arabic-Indic & Persian digits in phone field
      const phoneInput = document.getElementById('phone-input');
      const toWesternDigits = (str) => {
        return str
          .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))
          .replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
      };

      phoneInput.addEventListener('input', (e) => {
        const raw = e.target.value;
        const normalized = toWesternDigits(raw);
        if (raw !== normalized) {
          e.target.value = normalized;
        }
      });

      // 4. Pay button interaction confirmation
      const payButton = document.getElementById('pay-button');
      payButton.addEventListener('click', () => {
        payButton.style.opacity = '0.8';
        payButton.innerHTML = '<span>جاري المعالجة...</span>';
        setTimeout(() => {
          payButton.innerHTML = '<span>تم الدفع بنجاح ✓</span>';
          payButton.style.backgroundColor = '#059669';
          payButton.style.opacity = '1';
        }, 800);
      });
    });
  </script>
